public static String trimTrailingWhitespace(String str) {
    if (str == null || str.isEmpty()) {
        return str;
    }
    int len = str.length();
    int i = len - 1;
    while (i >= 0 && Character.isWhitespace(str.charAt(i))) {
        i--;
    }
    if (i < len - 1) {
        return str.substring(0, i + 1);
    }
    return str;
}

