/**
 * Transform from a Set representation to a graph path.
 * @param tour a set containing the edges of the tour
 * @param graph the graph
 * @return a graph path
 */
protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // Initialize an empty graph path
    GraphPath<V,E> path = new GraphPath<V,E>();

    // Iterate over the edges in the tour set
    for (E edge : tour) {
        // Get the source and target vertices of the edge
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        // If the source vertex is not already in the path, add it
        if (!path.containsVertex(source)) {
            path.addVertex(source);
        }

        // Add the edge to the path
        path.addEdge(edge);

        // If the target vertex is not already in the path, add it
        if (!path.containsVertex(target)) {
            path.addVertex(target);
        }
    }

    return path;
}

public GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }
    if (tour.size() < 2) {
        throw new IllegalArgumentException("Tour must have at least two edges");
    }
    if (!tour.stream().allMatch(edge -> graph.containsEdge(edge))) {
        throw new IllegalArgumentException("All edges in tour must be present in the graph");
    }

    List<E> edgeList = new ArrayList<>(tour);
    int numVertices = graph.vertexSet().size();
    int numEdges = edgeList.size();
    GraphPath<V,E> path = new GraphPath<>(numVertices, numEdges);

    for (int i = 0; i < numVertices; i++) {
        path.addVertex(graph.getVertexes().get(i));
    }

    for (int i = 0; i < numEdges; i++) {
        E edge = edgeList.get(i);
        path.addEdge(edge, graph.getEdgeSource(edge), graph.getEdgeTarget(edge));
    }

    return path;
}

