private String abbreviateName(String name) {
    // Early return if name is empty
    if (name.isEmpty()) return name;

    // Get the first character of the name
    char firstChar = name.charAt(0);

    // If the first character is a letter, return the name unchanged
    if (Character.isLetter(firstChar)) return name;

    // Otherwise, return the name with the first character upper-cased
    return Character.toUpperCase(firstChar) + name.substring(1);
}

