private static <V, E>boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the graph is null or the vertices are null
    if (graph == null || vertices == null) {
        return false;
    }

    // Check if the vertices are empty
    if (vertices.isEmpty()) {
        return true;
    }

    // Check if the graph has no edges
    if (graph.edgeSet().isEmpty()) {
        return false;
    }

    // Create a set of all edges in the graph
    Set<E> allEdges = new HashSet<E>(graph.edgeSet());

    // Create a set of all edges in the subgraph induced by the vertices
    Set<E> subgraphEdges = new HashSet<E>();
    for (V vertex : vertices) {
        subgraphEdges.addAll(graph.edgesOf(vertices));
    }

    // Check if the subgraph edges are the same as the all edges
    return allEdges.equals(subgraphEdges);
}

