 * @param vertices the vertices to induce the subgraph from.
 * @return true if the induced subgraph is a clique.
 */
private static <V,E>boolean isClique(Graph<V,E> graph,Set<V> vertices){
    int numVertices = vertices.size();
    if (numVertices == 0 || numVertices == 1) {
        return true;
    }
    int numEdges = 0;
    List<V> vertexList = new ArrayList<>(vertices);
    for (int i = 0; i < vertexList.size(); i++) {
        V vertex1 = vertexList.get(i);
        for (int j = i + 1; j < vertexList.size(); j++) {
            V vertex2 = vertexList.get(j);
            if (graph.hasEdgeConnecting(vertex1, vertex2)) {
                numEdges++;
            }
        }
    }
    return numEdges == (numVertices * (numVertices - 1)) / 2;
}

